        const errorMsg = error.message || String(error);

        if (errorMsg.includes('API_KEY_SERVICE_BLOCKED') || errorMsg.includes('PERMISSION_DENIED')) {
             return `Translation failed: Check API Key Restrictions in Google Cloud. (Changes take 5 mins)${keyHint}`;
        }

        if (errorMsg.includes('unauthorized domain') || errorMsg.includes('domain restriction')) {
            return `Translation failed: Access denied due to domain restrictions. In Google Cloud Console > Credentials > Edit Key > Application Restrictions (Websites), add your Vercel domain (e.g., https://your-app.vercel.app) or temporary 'None' restriction for debugging.${keyHint}`;
        }

        return `Translation failed. Please try again.${keyHint}`;
    }
};
