        const { products, freightTotal, destinationCostsTotal } = planData;
        if (!products || products.length === 0) {
            return {
                ...planData,
                totalUnitCost: 0, unitSalesMargin: 0, grossSalesMarginPercent: 0, grossMarkupPercent: 0,
                netMarkupPercent: 0, totalInvestment: 0, totalSales: 0, totalProfit: 0,
                interest15Percent: 0, netProfit: 0, netSalesMarginPercent: 0
            };
        }

        const totalQty = products.reduce((sum, p) => sum + (p.qtyInContainer || 0), 0);
        if (totalQty <= 0) {
            return {
                ...planData,
                totalUnitCost: 0, unitSalesMargin: 0, grossSalesMarginPercent: 0, grossMarkupPercent: 0,
                netMarkupPercent: 0, totalInvestment: 0, totalSales: 0, totalProfit: 0,
                interest15Percent: 0, netProfit: 0, netSalesMarginPercent: 0
            };
        }

        const totalFobCosts = products.reduce((sum, p) => sum + ((p.fobCostUnit || 0) * (p.qtyInContainer || 0)), 0);

        const totalInvestment = totalFobCosts + (freightTotal || 0) + (destinationCostsTotal || 0);
        const totalSales = products.reduce((sum, p) => sum + ((p.estimatedSalesPrice || 0) * (p.qtyInContainer || 0)), 0);

        const totalUnitCost = totalInvestment / totalQty; // Average unit cost
        const avgSalesPrice = totalSales / totalQty;
        const unitSalesMargin = avgSalesPrice - totalUnitCost; // Average margin

        const totalProfit = totalSales - totalInvestment;
        const grossSalesMarginPercent = totalSales > 0 ? ((totalSales - totalInvestment) / totalSales) * 100 : 0;
        const grossMarkupPercent = totalInvestment > 0 ? ((totalSales - totalInvestment) / totalInvestment) * 100 : 0;

        const interest15Percent = totalInvestment * 0.15;
        const netProfit = totalProfit - interest15Percent;
        const netSalesMarginPercent = totalSales > 0 ? (netProfit / totalSales) * 100 : 0;
        const netMarkupPercent = totalInvestment > 0 ? (netProfit / totalInvestment) * 100 : 0;

        return {
            ...planData,
            totalUnitCost, unitSalesMargin, totalInvestment, totalSales, totalProfit,
            grossSalesMarginPercent, grossMarkupPercent, interest15Percent, netProfit,
            netSalesMarginPercent, netMarkupPercent
        };
